			rangeFragment = fmt.Sprintf("L%d", rangeStart)
		}
		return fmt.Sprintf("blob/%s/%s?plain=1#%s", branchName, filePath, rangeFragment), nil
	}
	return fmt.Sprintf("tree/%s/%s", branchName, filePath), nil
