		s := "  " + rpad(c.Name()+":", c.NamePadding()) + c.Short
		if includes(coreCommandNames, c.Name()) {
			coreCommands = append(coreCommands, s)
		} else {
			additionalCommands = append(additionalCommands, s)
		}
	}

	helpEntries := []helpEntry{
